export const categories = ['Canned goods', 'Dry goods', 'Produce', 'Toiletries'] as const;

export type Category = (typeof categories)[number];

export type PantryItem = {
  id: string;
  name: string;
  category: Category;
  quantity: number;
  /** ISO date, YYYY-MM-DD. */
  lastRestocked: string;
};

/** Below this many on hand, an item is flagged as running low. */
export const LOW_STOCK = 10;

export const sampleItems: PantryItem[] = [
  { id: 'black-beans', name: 'Black beans', category: 'Canned goods', quantity: 48, lastRestocked: '2026-10-08' },
  { id: 'chopped-tomatoes', name: 'Chopped tomatoes', category: 'Canned goods', quantity: 6, lastRestocked: '2026-09-27' },
  { id: 'brown-rice', name: 'Brown rice', category: 'Dry goods', quantity: 22, lastRestocked: '2026-10-05' },
  { id: 'rolled-oats', name: 'Rolled oats', category: 'Dry goods', quantity: 15, lastRestocked: '2026-10-02' },
  { id: 'apples', name: 'Apples', category: 'Produce', quantity: 30, lastRestocked: '2026-10-10' },
  { id: 'potatoes', name: 'Potatoes', category: 'Produce', quantity: 8, lastRestocked: '2026-10-09' },
  { id: 'toothpaste', name: 'Toothpaste', category: 'Toiletries', quantity: 12, lastRestocked: '2026-09-30' },
  { id: 'bar-soap', name: 'Bar soap', category: 'Toiletries', quantity: 4, lastRestocked: '2026-09-21' },
];

const dateFormat = new Intl.DateTimeFormat('en-US', { dateStyle: 'medium', timeZone: 'UTC' });

/** Formats an ISO date the same way on the server and in every browser time zone. */
export function formatDate(iso: string) {
  return dateFormat.format(new Date(`${iso}T00:00:00Z`));
}

/** Today's local date as YYYY-MM-DD. */
export function today() {
  const now = new Date();
  const pad = (value: number) => String(value).padStart(2, '0');
  return `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;
}

export function slug(name: string) {
  return name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}
